// Тестовый маршрут иврита для браузерного теста экрана «С нуля»: подставляется вместо c-zero-he.js. Есть ивритский текст, таблица и сборка слова справа налево.
import { choose, listen, typed, order, match, read } from './zero-kit.js';

const lesson = (n, needs, o = {}) => ({
  id: `hz-0${n}`, title: `Тестовый урок иврита ${n}`, minutes: 4, stage: 'Письмо', needs, intro: '',
  goal: `прочитать слово шалом в тестовом уроке ${n}`,
  body: [`Слово «שלום» читается справа налево: шалом. Это тестовый урок иврита ${n}.`, 'Второй абзац урока: ивритские буквы идут справа налево, а русский текст слева направо.'],
  table: [['Буква', 'Название'], ['א', 'алеф'], ['ב', 'бет']],
  words: ['שלום'],
  task: `Скажи вслух слово «שלום» и покажи пальцем, с какой стороны оно начинается (урок ${n}).`,
  cards: [[`Как называется буква א (урок ${n})?`, 'Алеф'], [`С какой стороны читают иврит (урок ${n})?`, 'Справа налево']],
  drills: [
    choose(`Иврит ${n}: с какой стороны начинается строка?`, 'Справа', ['Слева', 'Сверху'], { hint: 'Иврит идёт справа налево' }),
    choose(`Иврит ${n}: как называется эта буква?`, 'алеф', ['бет', 'гимель'], { big: 'א', lang: 'hebrew', hint: 'Это первая буква' }),
    listen('שלום', 'שלום', ['שמש', 'שבת'], { q: `Иврит ${n}: какое слово ты услышал?`, lang: 'hebrew' }),
    typed(`Иврит ${n}: впиши название буквы ב`, ['бет'], { explain: 'Буква ב называется бет.' }),
    order(`Иврит ${n}: собери слово из букв`, ['ש', 'ל', 'ו', 'ם'], { dir: 'rtl', say: 'שלום', lang: 'hebrew' }),
    match(`Иврит ${n}: соедини букву и название`, [['א', 'алеф'], ['ב', 'бет'], ['ג', 'гимель']], { lang: 'hebrew' }),
    choose(`Иврит ${n}: куда идёт русский текст?`, 'Слева направо', ['Справа налево', 'Снизу вверх']),
    read(`Прочитай вслух: שלום (урок ${n})`, { lang: 'hebrew' }),
  ],
  ...o,
});

export default {
  id: 'hezero', title: 'Иврит: письмо и чтение с нуля', icon: 'א', color: '#0f766e', zero: true, lang: 'hebrew', branch: 'modern', after: 'hebrew',
  resources: ['hebrewpod101', 'hebrewglot', 'duolingo', 'anki'],
  mentor: { name: 'Наставник', role: 'Тестовый курс иврита', principles: ['Первое правило курса.', 'Второе правило курса.', 'Третье правило курса.', 'Четвёртое правило курса.'], prompts: ['Первый запрос.', 'Второй запрос.', 'Третий запрос.'] },
  intro: 'Тестовый маршрут иврита для проверки экрана «С нуля»: три урока по цепочке.',
  plan: [{ week: 1, focus: 'Первая неделя', daily: '15 минут' }, { week: 2, focus: 'Вторая неделя', daily: '15 минут' }, { week: 3, focus: 'Третья неделя', daily: '15 минут' }, { week: 4, focus: 'Четвёртая неделя', daily: '15 минут' }],
  sources: ['Первый источник тестового курса', 'Второй источник тестового курса'],
  lessons: [lesson(1, []), lesson(2, ['hz-01']), lesson(3, ['hz-02'])],
};
